#!/usr/bin/env bash
# E12-S3: the git guards the pages rely on are installed and required.
#   Part 1  the rules, pinned whole, unit by unit: preflight offers pre-commit in its one install ask; build step
#           41c switches the hooks on, makes the first save (gitleaks scans it) and moves the project to `work`;
#           Q12 is [BLOCK]; the catch-up (/resume-it) and /retrofit-it switch the hooks on; every skill that saves
#           for the user runs the same hook check first, saves nothing on HOOKS OFF, and reads the commit's exit
#           code; the skills that assume a branch after a build name `work`; the scaffolds' configs.
#   Part 2  the hook check itself, and /try-it's save line, run as written in throwaway repos
#   Part 3  REAL behaviour: a throwaway copy of the scaffold, step 41c run as written (twice), then: a token in
#           the first save stops it; a save on main is refused; a key in backend/tests/ or mock-services/ is
#           found; a .tsx and a .py save on `work` go through with Docker absent (the frontend checks print
#           their skip line) and, when Docker is here, with the frontend checks run in the container.
#           Needs pre-commit and the network (it fetches the hooks): without them it says SKIPPED loudly, and
#           fails in CI, where the workflow installs pre-commit.
# Keys are built at run time; no secret is written in this repository.
set -uo pipefail
cd "$(dirname "$0")/.."
fail=0
ok()  { echo "ok    $*"; }
bad() { echo "FAIL  $*"; fail=1; }
T="$(mktemp -d)"; trap 'chmod -R u+w "$T" 2>/dev/null; rm -rf "$T"' EXIT
MK=.claude/commands/make-it.md; GO=.claude/make-it/references/git-operations.md
SC=.claude/make-it/scaffolds/fastapi-nextjs; SF=.claude/make-it/scaffolds/nextjs-fullstack

# --- Part 1: the rules, pinned whole --------------------------------------------------------------
python3 - <<'PY' || fail=1
import re, sys
flat = lambda s: re.sub(r"\s+", " ", s).strip()
UNITS = [
    ('make-it preflight checks pre-commit', '.claude/commands/make-it.md', "pre-commit --version 2>/dev/null   # runs the project's checks before every save (prerequisites.md #6)"),
    ('prerequisites #6 pre-commit', '.claude/make-it/references/prerequisites.md', '### 6. pre-commit\n\n**Why needed:** Runs the project\'s checks before every save: gitleaks\' scan for passwords and keys, and `no-commit-to-branch`, which stops a save straight to `main`. /make-it switches them on in every build (check Q12), and the skills that save for the user save nothing while they are off.\n**How to check:** `pre-commit --version 2>/dev/null`\n**What to tell the user it is:** "pre-commit -- runs your project\'s checks before every save: a scan for passwords and keys, and a stop on saving straight to the main copy"\n**If missing:** it is a Quick Fix, offered in preflight\'s one install ask with the other missing tools (a pick: install it, walk them through it, or their company\'s way), never installed without it.\n- macOS: `brew install pre-commit`\n- Windows: `py -m pip install --user pre-commit`\n- Linux: `pipx install pre-commit` or `python3 -m pip install --user pre-commit`'),
    ('prerequisites: the instant check', '.claude/make-it/references/prerequisites.md', '- pre-commit installed? `pre-commit --version 2>/dev/null`'),
    ('prerequisites: a quick fix', '.claude/make-it/references/prerequisites.md', '- Examples: Docker, GitHub CLI, VS Code, pre-commit'),
    ('make-it step b points at 41c and work', '.claude/commands/make-it.md', 'Step 41c switches these hooks on (`pre-commit install`), makes the first save, and moves the\n      project to its working branch, `work`. After that first save, all work goes on `work` or a\n      worktree branched from it (`scripts/worktree.sh new <branch>`), never on `main`/`master`.'),
    ('make-it step 41c', '.claude/commands/make-it.md', '41c. **Switch on the checks before every save, save the build, and move to `work` (silent -- checks\nQ12, VC02).** The hooks go on first, so the first save is checked too: gitleaks scans everything\nit saves. That one save skips `no-commit-to-branch` (it is the save that belongs on the default\nbranch), the two frontend checks that run in Docker, and ruff (the scaffold\'s own Python doesn\'t\npass it yet). Then the project moves to a working branch, `work`, so every later save goes there\nand the default branch stays as the build left it until /ship-it. Before it, run `git status --short` and check that\nnothing secret-looking is about to be saved (never save a `.env` or key file; the scaffold\'s\n`.gitignore` leaves them out). Then, in the project (safe to run again):\n\n```bash\npre-commit install || { echo "HOOKS NOT ON"; exit 1; }\nhk="$(git rev-parse --git-path hooks/pre-commit)"\n[ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk" || { echo "HOOKS NOT ON"; exit 1; }\n# gitleaks reads what a save adds against the save before it, so the build goes on top of an empty one\ngit rev-parse -q --verify HEAD >/dev/null ||\n  SKIP=no-commit-to-branch git commit -q --allow-empty -m "Start" || { echo "FIRST SAVE REFUSED"; exit 1; }\nif [ "$(git rev-list --count HEAD)" = 1 ]; then\n  git add -A && SKIP=no-commit-to-branch,eslint,prettier,ruff,ruff-format git commit -q -m "Initial build" ||\n    { echo "FIRST SAVE REFUSED"; exit 1; }\nfi\n[ "$(git branch --show-current)" = work ] || git switch -q work 2>/dev/null || git switch -q -c work || { echo "NO WORK BRANCH"; exit 1; }\necho "HOOKS ON"\n```\n\nIt must print `HOOKS ON` (Q12 is [BLOCK]). Otherwise fix the cause and run it again:\n- `HOOKS NOT ON`: `pre-commit install` printed why above it. `pre-commit` missing: preflight\'s\n  install ask for it. Another tool already manages this project\'s git hooks (`core.hooksPath` is\n  set): stop before /try-it and tell the user: "I couldn\'t switch on the checks your project runs\n  before every save (a scan for passwords and keys, and a stop on saving straight to the main\n  copy), so I\'ve stopped before showing you the app. [the reason, in plain words]"\n- `FIRST SAVE REFUSED`: a hook that tidies files (trailing spaces, line endings) changed some --\n  run it again and they are saved; gitleaks found a value that looks like a password or key --\n  move it into `.env` (as the security step does), then run it again; git doesn\'t know the user\'s\n  name and email -- ask for them.\n\nThen tell the user, in one line: "Your project\'s saves go on a working copy called \'work\'; the main\ncopy stays clean until you ship."'),
    ('make-it state file records the branch', '.claude/commands/make-it.md', 'Working branch: `work` (every save goes here; `main` holds the first build until /ship-it).'),
    ('Q12 [BLOCK]', '.claude/make-it/references/build-standards.md', "**Q12** [Tier 0] [BLOCK] **Pre-commit hooks installed locally** -- When `.pre-commit-config.yaml` exists, the file git runs before each commit (`git rev-parse --git-path hooks/pre-commit`) exists, can be run, and is pre-commit's own: it holds `File generated by pre-commit`. /make-it runs `pre-commit install` before the build's first save (build-verify step 41c, which then moves the project to its `work` branch), so in its first build-verify the check is made there, not in Part A. /resume-it's catch-up and /retrofit-it switch it on when it is off (one plain line), asking preflight's install pick for `pre-commit` first when it is missing. /wrap-it, /try-it, /argo-it, /fix-it, /resume-it, /retrofit-it and /deadcode-it run the same check before every save they make for the user and save nothing while it fails (`git-operations.md`, Before any save); the one save built with the hooks off by design is /argo-it's first-deploy save, which holds only argo-it's files and is checked by its own secret scan. CI does not depend on pre-commit hooks."),
    ('Q08 gitleaks rules and allowlist', '.claude/make-it/references/build-standards.md', "**Q08** [Tier 0] [FIX] **Secret detection configured (gitleaks)** -- `.gitleaks.toml` exists at project root. gitleaks hook is in `.pre-commit-config.yaml`. The allowlist names only known mock values (the mock-token patterns) and exact files (`.env.example`, the mock seed script), each path anchored -- never a whole folder such as `tests/` or `mock-services/`, which would hide a real key put there. The file extends gitleaks' default rules (`[extend]` with `useDefault = true`): a config that only lists allowlists has no rules, and gitleaks finds nothing."),
    ('git-operations: Before any save, After the save, The branch', '.claude/make-it/references/git-operations.md', '### Before any save\n\nA save a skill makes for the user never goes ahead with the project\'s hooks switched off. Before\nit, run:\n\n```bash\nhk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || echo "HOOKS OFF"\n```\n\nIt prints `HOOKS OFF` when the project has a `.pre-commit-config.yaml` but git has no working\npre-commit hook to run (check Q12). Then nothing is saved, and the user hears: "I haven\'t saved\nanything: the checks this project runs before every save (a scan for passwords and keys, and a stop\non saving straight to the main copy) are switched off on this computer. Run /resume-it to switch\nthem on." A project with no `.pre-commit-config.yaml` saves as before. Never get past it with\n`--no-verify`. The build\'s first save (/make-it step 41c) and /resume-it\'s Desktop hand-off are\nmade by the step that switches the hooks on. One save is built with the hooks off by design:\n/argo-it\'s first-deploy save (PHASE 5), which holds only argo-it\'s own files and is checked by its\nown secret scan before anything is sent.\n\n**After the save**, read `git commit`\'s exit code (never throw it away with `2>/dev/null` or\n`|| true`). Anything but 0 means nothing was saved: never say it was. Tell the user, from what the\nhook printed: "I couldn\'t save your changes: [what stopped it, in plain words -- the scan for\npasswords and keys found one in [file], line [N] / it would have saved straight to the main copy /\na check of the code failed in [file]]. They\'re still in your files, unsaved. [what to do next, in\nplain words]" -- never the value itself.\n\n**The branch.** A /make-it project works on `work`: step 41c moves it there after the first save,\nso every save a skill makes lands on `work` (or a worktree branched from it), and `main` holds the\nfirst build until /ship-it sends `work` in for review. A project /make-it didn\'t build (one\n/retrofit-it upgrades, say) keeps its own branches.'),
    ('git-operations: the shipped hook', '.claude/make-it/references/git-operations.md', "make-it's installers add a Claude Code hook that refuses `git push --force`, `-f`, `--mirror`\n  and `+refspec` pushes (`~/.claude/make-it/hooks/no-force-push.sh`) and lets `--force-with-lease`\n  through."),
    ('worktree-workflow: /make-it moves to work', '.claude/make-it/references/worktree-workflow.md', '- **/make-it** — scaffolds `scripts/worktree.sh`, the `no-commit-to-branch` hook, and the\n  parameterized compose into every project; step 41c switches the hooks on, makes the first save\n  on the default branch, and moves the project to its working branch, `work`. Feature work goes\n  on `work` or a worktree branched from it; `main` stays as the build left it until /ship-it.'),
    ('worktree-workflow: /ship-it ships work', '.claude/make-it/references/worktree-workflow.md', "- **/ship-it** — ships the current worktree's branch (`work` after a build); the default branch stays clean."),
    ('ship-it-guide: the branch it sends', '.claude/make-it/references/ship-it-guide.md', "**The branch it sends.** A /make-it project is on `work` when /ship-it runs: the build's step 41c\nmade the first save on `main` and moved every later save to `work`. So /ship-it sends `work` (or\nthe branch of the worktree it runs in) as the pull request's branch, into `main`; it never commits\nto `main` (the project's `no-commit-to-branch` hook refuses that) and never pushes `main` past the\nfirst build. On the first ship, GitHub has no `main` yet: /ship-it pushes `main` as the build left\nit, then opens the pull request from `work`. /ship-it is a separate plugin: until its SKILL.md says\nthis, the person running it should expect it to send `work`, and say so if it offers to commit on\n`main`."),
    ('resume-it Desktop a ends on work', '.claude/commands/resume-it.md', 'then save the\n  bundle as /make-it\'s step 41c does: with a `.pre-commit-config.yaml`, run that step\'s block as\n  written (hooks on, the first save on the default branch, then `work`); without one,\n  `git add -A && git commit -m "Initial build" && git switch -c work`. Either way it ends on\n  `work`, and all further work goes there (WORKTREE FIRST, below).'),
    ('resume-it Desktop c follows 41c', '.claude/commands/resume-it.md', "Before `build-verify`'s step 41c (hooks on, the first save on the default branch, then `work`),\n  do step a's `.gitignore` and `git status` secret check; feature work then goes on `work`."),
    ('resume-it worktree-first branches from work', '.claude/commands/resume-it.md', '`scripts/worktree.sh new <branch>` (it branches from where you are: `work` in a project /make-it\nbuilt, so `main` stays as the build left it until /ship-it).'),
    ('resume-it catch-up Q12', '.claude/commands/resume-it.md', '- **Hooks on (Q12):** when `.pre-commit-config.yaml` exists and the hook check (`git-operations.md`, Before any save) prints `HOOKS OFF`: if `pre-commit` is installed, run `pre-commit install` now -- routine, no ask -- and say one line: "I switched on the checks your project runs before every save: a scan for passwords and keys, and a stop on saving straight to the main copy." If `pre-commit` isn\'t installed, ask preflight\'s install pick for it (`make-it.md` preflight, the one ask for missing tools), then switch the hooks on the same way. If `pre-commit install` fails, say why in plain words (another tool already manages this project\'s git hooks, for example) and that the checks stay off. Q12 never goes in the gaps list or its ask.'),
    ('resume-it save', '.claude/commands/resume-it.md', 'Before that commit, run the hook check (`git-operations.md`, Before any save):\n`hk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || echo "HOOKS OFF"`.\nIf it prints `HOOKS OFF` (the catch-up couldn\'t switch the hooks on, or the user turned down\ninstalling pre-commit), commit nothing and say: "I haven\'t saved anything: the checks this project\nruns before every save (a scan for passwords and keys, and a stop on saving straight to the main\ncopy) are switched off on this computer. Say \'switch on the save checks\' and I\'ll set them up." After\nthe commit, read its exit code: anything but 0 means nothing was saved -- never say it was; say the\n"couldn\'t save" line (`git-operations.md`, After the save).'),
    ('retrofit Verify Q12', '.claude/commands/retrofit-it.md', "- **Q01-Q16**: Code quality (Q14, the dead-code upkeep reminder, is N/A right after a retrofit; Q12 is switched on the way /resume-it's catch-up does it, with its one plain line)"),
    ('retrofit snapshot Q12, no work branch', '.claude/commands/retrofit-it.md', '**Before the snapshot, the hooks (Q12):** when the app has its own repo and a\n`.pre-commit-config.yaml`, run the hook check (`git-operations.md`, Before any save). On `HOOKS\nOFF`, switch the hooks on the way /resume-it\'s catch-up does (Q12: `pre-commit install` and its one\nplain line, preflight\'s install pick first when `pre-commit` is missing), then run the check again.\nStill `HOOKS OFF`: stop here, before any change, and tell the user: "I haven\'t changed or saved\nanything: the checks this project runs before every save (a scan for passwords and keys, and a stop\non saving straight to the main copy) are switched off on this computer. [when `pre-commit install`\nfailed: the reason, in plain words / otherwise: Run /retrofit-it again and pick Install when I ask\nabout pre-commit.]" A folder that wasn\'t under git yet gets the same step right after the\nsnapshot, before Phase 5: its snapshot is its first save, the one `pre-commit install` follows.\nUnlike /make-it\'s step 41c, nothing here moves the app to a `work` branch: an existing repo keeps\nits own branches, and Phase 5 makes the retrofit\'s own branch as it always has.'),
    ('wrap-it save: the hook check', '.claude/commands/wrap-it.md', '- Before staging anything, run the hook check (`git-operations.md`, Before any save):\n  `hk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || echo "HOOKS OFF"`. If it prints `HOOKS OFF`, save nothing and say, in place of the save\n  line: "I haven\'t saved anything: the checks this project runs before every save (a scan for passwords and keys, and a stop on saving straight to the main copy) are switched off on this computer. Run /resume-it to switch them on." The rest of the wrap-up goes on.'),
    ('wrap-it save: the exit code', '.claude/commands/wrap-it.md', '- Read the commit\'s exit code. Anything but 0 means nothing was saved (a hook refused it): never\n  say "Saved your changes". Say instead: "I couldn\'t save your changes: [what stopped it, in plain\n  words, from what the hook printed -- the scan for passwords and keys found one in [file], line\n  [N] / it would have saved straight to the main copy / a check of the code failed in [file]].\n  They\'re still on this computer, unsaved, so nothing is lost. [what to do next, in plain words]"\n  The rest of the wrap-up goes on.'),
    ('try-it save: exit code and hook check', '.claude/commands/try-it.md', '- Unless an update is unfinished (above), stage and commit any fixes: `git add -A -- . \':(exclude).ship-it-go-live.json\' && { git diff --cached --quiet || git commit -m "Apply safety patches" -- . \':(exclude).ship-it-go-live.json\'; }`\n  (after a /make-it build this lands on `work`). If it exits with anything but 0, nothing was saved:\n  never say the patches were saved; when the app is presented, say the "couldn\'t save" line\n  (`git-operations.md`, After the save), filled from what the hook printed.\n- Before that save, run the hook check (`git-operations.md`, Before any save): `hk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || echo "HOOKS OFF"`.\n  If it prints `HOOKS OFF`, commit nothing, and when the app is presented say: "I haven\'t saved anything: the checks this project runs before every save (a scan for passwords and keys, and a stop on saving straight to the main copy) are switched off on this computer. Run /resume-it to switch them on."'),
    ('argo-it 5b step 4 hook check', '.claude/commands/argo-it.md', '# The project\'s checks before every save must be on: a .pre-commit-config.yaml and no pre-commit hook saves nothing\nhk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || { echo "HOOKS OFF"; exit 3; }'),
    ('argo-it HOOKS OFF rule', '.claude/commands/argo-it.md', '**If the block prints `HOOKS OFF`, stop here -- nothing was saved or sent.** The project has a\n`.pre-commit-config.yaml`, but git has no pre-commit hook to run (`git-operations.md`, Before any\nsave). Tell the user: "I haven\'t saved or sent anything: the checks this project runs before every\nsave (a scan for passwords and keys, and a stop on saving straight to the main copy) are switched\noff on this computer. What to do next: run /resume-it to switch them on, then run /argo-it again."'),
    ('fix-it branch options', '.claude/commands/fix-it.md', '2. Work on the current branch (`[current branch]`), one commit for everything\n3. Work on the current branch (`[current branch]`), one commit per fix category\n4. Not now -- nothing is changed\n\nPick one."\n\n`[current branch]` is `git branch --show-current` (`work` after a /make-it build). When it is\n`main` or `master` and the project\'s `.pre-commit-config.yaml` has `no-commit-to-branch`, leave\noptions 2 and 3 out: that hook refuses every save there.'),
    ('fix-it saves', '.claude/commands/fix-it.md', '**Before any commit in Steps 7-9**, run the hook check (`git-operations.md`, Before any save):\n`hk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || echo "HOOKS OFF"`. If it prints `HOOKS OFF`, commit nothing: the fixes stay in the files,\nunsaved, and the report opens with: "I haven\'t saved anything: the checks this project runs before every save (a scan for passwords and keys, and a stop on saving straight to the main copy) are switched off on this computer. Run /resume-it to switch them on." After each commit, read its exit code: anything but 0 means\nthat finding\'s fix wasn\'t saved -- say so in its report line with the "couldn\'t save" line\n(`git-operations.md`, After the save), never "closed".'),
    ('deadcode-it precondition points at the check', '.claude/commands/deadcode-it.md', '(after the hook check in `delete-safe`; one commit of exactly those files on the current branch, message `chore: save work before'),
    ('deadcode-it saves', '.claude/commands/deadcode-it.md', 'Before the first save (precondition 3\'s "Save them", or the first batch), run the hook check\n(`git-operations.md`, Before any save): `hk="$(git rev-parse --git-path hooks/pre-commit)"; [ ! -f "$(git rev-parse --show-toplevel)/.pre-commit-config.yaml" ] || { [ -x "$hk" ] && grep -qs \'File generated by pre-commit\' "$hk"; } || echo "HOOKS OFF"`. On `HOOKS OFF`, save\nnothing, delete nothing more, and stop with: "I haven\'t saved anything: the checks this project runs before every save (a scan for passwords and keys, and a stop on saving straight to the main copy) are switched off on this computer. Run /resume-it to switch them on." After each save, read the commit\'s exit code:\nanything but 0 means that batch wasn\'t saved -- put its files back as they were, and say so with the\n"couldn\'t save" line (`git-operations.md`, After the save), never "Removed".'),
]
bad = 0
for label, f, text in UNITS:
    if flat(text) in flat(open(f, encoding="utf-8").read()):
        print("ok    %s pins: %s" % (f, label))
    else:
        print("FAIL  %s lacks: %s" % (f, label)); bad = 1
sys.exit(bad)
PY
BS=.claude/make-it/references/build-standards.md
if grep -q 'Q12\*\* \[Tier 0\] \[WARN\]' "$BS"; then bad "Q12 is still [WARN]"; else ok "Q12 is no longer [WARN]"; fi
if grep -qiE 'where (it is |pre-commit is )?installed' "$BS" "$GO"; then bad "a 'where installed' escape is in the rules"; else ok "no 'where installed' escape in the rules"; fi
if grep -nE -- 'git (commit|push|merge|rebase|am)[^`]*--no-verify' .claude/commands/*.md .claude/make-it/references/*.md >/dev/null; then bad "a skill runs git with --no-verify"; else ok "no skill runs git with --no-verify"; fi
grep -n 'git commit' .claude/commands/try-it.md | grep -q '2>/dev/null' && bad "try-it's save still throws its error away" || ok "try-it's save keeps its error output"
# the scaffolds: hooks that run on any machine, the frontend checks in the container, gitleaks with its rules
for d in "$SC" "$SF"; do
  grep -q '^default_language_version:' "$d/.pre-commit-config.yaml" && bad "$d: hooks still need one exact python" || ok "$d: the hooks run with any python3"
  grep -q 'no-commit-to-branch' "$d/.pre-commit-config.yaml" && grep -q 'id: gitleaks' "$d/.pre-commit-config.yaml" && ok "$d: config has no-commit-to-branch and gitleaks" || bad "$d: config lost a guard"
  [ "$(grep -c 'entry: bash scripts/precommit-in-container.sh' "$d/.pre-commit-config.yaml")" = 2 ] && [ -x "$d/scripts/precommit-in-container.sh" ] && ! grep -q 'npx ' "$d/.pre-commit-config.yaml" \
    && ok "$d: eslint and prettier run through the container script, never npx on the host" || bad "$d: a frontend hook still needs the app's packages on the host"
  python3 -c 'import sys,tomllib; d=tomllib.load(open(sys.argv[1],"rb")); a=d.get("allowlist",{}); ps=a.get("paths",[])
sys.exit(0 if d.get("extend",{}).get("useDefault") is True and all(p.startswith(("^","(^|/)")) for p in ps) and not any("tests/" in p or "mock-services/" in p for p in ps) else 1)' "$d/.gitleaks.toml" \
    && ok "$d: .gitleaks.toml keeps the default rules, allowlists no folder, anchors every path" || bad "$d: .gitleaks.toml has no rules, or allowlists a folder"
done
cmp -s "$SC/scripts/precommit-in-container.sh" "$SF/scripts/precommit-in-container.sh" && ok "both scaffolds ship the same container script" || bad "the scaffolds' container scripts differ"

# --- Part 2: the hook check, and try-it's save line, run as written ----------------------------------
gate_line=$(python3 - "$GO" <<'PY'
import re, sys
t = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"### Before any save.*?```bash\n(.*?)\n```", t, re.S)
print(m.group(1) if m else "")
PY
)
if [ -z "$gate_line" ]; then bad "no hook check found in git-operations.md to run"; else
  git init -q -b main "$T/g" && cd "$T/g"
  [ -z "$(bash -c "$gate_line")" ] && ok "check: no .pre-commit-config.yaml -> nothing printed (saves as before)" || bad "check: a project without pre-commit was stopped"
  echo 'repos: []' > .pre-commit-config.yaml
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: config and no hook -> HOOKS OFF" || bad "check: config and no hook was not stopped"
  mkdir -p sub && [ "$(cd sub && bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: run from a subfolder -> HOOKS OFF" || bad "check: missed from a subfolder"
  printf '#!/bin/sh\nexit 0\n' > .git/hooks/pre-commit; chmod +x .git/hooks/pre-commit
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: some other pre-commit hook -> HOOKS OFF" || bad "check: a hook that isn't pre-commit's passed"
  printf '#!/usr/bin/env bash\n# File generated by pre-commit: https://pre-commit.com\n' > .git/hooks/pre-commit
  [ -z "$(bash -c "$gate_line")" ] && ok "check: pre-commit's hook -> nothing printed" || bad "check: pre-commit's own hook was refused"
  chmod -x .git/hooks/pre-commit
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: pre-commit's hook that can't be run (git skips it) -> HOOKS OFF" || bad "check: a hook git would skip passed"
  chmod +x .git/hooks/pre-commit
  git config core.hooksPath "$T/elsewhere"
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: core.hooksPath points away from the hook -> HOOKS OFF" || bad "check: core.hooksPath hid a missing hook"
  git config --unset core.hooksPath
  git worktree add -q "$T/g-wt" -b wt 2>/dev/null; cp .pre-commit-config.yaml "$T/g-wt/"
  [ -z "$(cd "$T/g-wt" && bash -c "$gate_line")" ] && ok "check: a worktree shares the repo's hook" || bad "check: a worktree was stopped though the hook is there"
  cd - >/dev/null
fi
# try-it's save, run as written under a hook that refuses: its exit code and the hook's words reach the skill
tryline=$(python3 - <<'PY'
import re
t = open(".claude/commands/try-it.md", encoding="utf-8").read()
m = re.search(r"stage and commit any fixes: `([^`]*git commit[^`]*)`", t)
print(m.group(1) if m else "")
PY
)
if [ -z "$tryline" ]; then bad "no try-it save line found to run"; else
  git init -q -b main "$T/tr" && cd "$T/tr" && git config user.name t && git config user.email t@example.invalid
  git commit -q --allow-empty -m base; printf '#!/bin/sh\necho "refused by the test hook" >&2\nexit 1\n' > .git/hooks/pre-commit; chmod +x .git/hooks/pre-commit
  echo x > fix.txt
  out=$(bash -c "$tryline" 2>&1); rc=$?
  [ "$rc" != 0 ] && case $out in *"refused by the test hook"*) true ;; *) false ;; esac && [ "$(git rev-list --count HEAD)" = 1 ] \
    && ok "try-it's save under a refusing hook: non-zero exit and the hook's words come back, nothing saved" || bad "try-it's save hid a refusal (exit $rc: $out)"
  rm -f .git/hooks/pre-commit; git add -A; git commit -q -m clean; out=$(bash -c "$tryline" 2>&1); rc=$?
  [ "$rc" = 0 ] && ok "try-it's save with nothing to save exits 0 (not read as a refusal)" || bad "try-it's save with nothing to save failed ($rc: $out)"
  cd - >/dev/null
fi

# --- Part 3: real behaviour ---------------------------------------------------------------------------
skip3() { echo "SKIPPED  Part 3 (real saves through the scaffold's hooks): $1 -- NOT PROVEN on this machine"; [ -z "${CI:-}" ] || bad "Part 3 skipped in CI: $1"; }
block41=$(python3 - "$MK" <<'PY'
import re, sys
t = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"^41c\. .*?```bash\n(.*?)\n```", t, re.S | re.M)
print(m.group(1) if m else "")
PY
)
key() { python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("gh"+"p_"+"".join(secrets.choice(a) for _ in range(36)))'; }
newapp() {  # a throwaway copy of the scaffold with its placeholders filled, git started, an identity set
  rm -rf "$1"; mkdir -p "$1"
  rsync -a --exclude README.md "$OLDROOT/$SC/" "$1/"
  (cd "$1" && grep -rlI '\[APP_SLUG\]\|\[APP_NAME\]' . | xargs sed -i.bak -e 's/\[APP_SLUG\]/guards-test/g' -e 's/\[APP_NAME\]/Guards Test/g' && find . -name '*.bak' -delete
   git init -q -b main . && git config user.name "git guards test" && git config user.email "guards@example.invalid")
}
OLDROOT=$PWD
if ! command -v pre-commit >/dev/null 2>&1; then skip3 "pre-commit is not installed"
elif ! command -v rsync >/dev/null 2>&1; then skip3 "rsync is not installed"
elif [ -z "$block41" ]; then bad "no step 41c block found in make-it.md to run"
else
  # 1. a token in the build's first save stops it: gitleaks scans the first save
  newapp "$T/first"; cd "$T/first"
  k=$(key); printf 'TOKEN = "%s"\n' "$k" > backend/app/settings_local.py
  out=$(bash -c "$block41" 2>&1)
  if ! pre-commit install-hooks >"$T/ih" 2>&1; then skip3 "the hooks could not be fetched (no network?): $(tail -2 "$T/ih" | tr '\n' ' ')"
  else
    case $out in *"FIRST SAVE REFUSED"*) [ "$(git rev-list --count HEAD 2>/dev/null)" = 1 ] && ! printf '%s' "$out" | grep -qF "$k" && ok "41c: a token in the first save stops it (gitleaks scanned it), unsaved, the token not printed" || bad "41c: refused, but saved or printed the token" ;;
      *) bad "41c: the first save went through with a token in it: $out" ;; esac
    rm -f backend/app/settings_local.py
    # 2. as written, twice: hooks on, one save on main, ends on work; the second run changes nothing
    out=$(bash -c "$block41" 2>&1); out2=$(bash -c "$block41" 2>&1)
    if [ "${out##*$'\n'}" = "HOOKS ON" ] && [ "${out2##*$'\n'}" = "HOOKS ON" ] && [ -x .git/hooks/pre-commit ] && [ "$(git rev-list --count main)" = 2 ] && [ "$(git branch --show-current)" = work ] && [ "$(git rev-list --count HEAD)" = 2 ]; then
      ok "41c, run as written twice: hooks on, the empty start and the build saved on main, the project on work, the second run a no-op"
    else bad "41c did not end with HOOKS ON on work: $out / $out2"; fi
    # 3. a save on main is refused by no-commit-to-branch
    git switch -q main; echo more >> .gitignore; git add .gitignore
    if git commit -q -m "straight to main" >"$T/c1" 2>&1; then bad "a save straight to main went through"
    else grep -q "commit to branch" "$T/c1" && ok "a save straight to main is refused by no-commit-to-branch" || bad "a save to main failed, but not by no-commit-to-branch: $(tail -3 "$T/c1")"; fi
    git reset -q --hard; git switch -q work
    # 4. keys in backend/tests/ and mock-services/ are found (no folder is allowlisted)
    for f in backend/tests/test_planted.py mock-services/planted/server.py; do
      mkdir -p "$(dirname "$f")"; k=$(key); printf 'TOKEN = "%s"\n' "$k" > "$f"; git add "$f"
      if git commit -q -m "a key" >"$T/c2" 2>&1; then bad "a key in $f went through"; git reset -q --hard HEAD~1
      else
        grep -q "Detect hardcoded secrets.*Failed" "$T/c2" && ok "a key in $f is refused by gitleaks" || bad "a key in $f was refused, but not by gitleaks: $(grep -E 'Failed|Passed' "$T/c2" | tr '\n' ' ')"
        grep -qF "$k" "$T/c2" && bad "the refusal of a key in $f printed the key" || ok "the refusal of a key in $f doesn't print the key"
        git reset -q
      fi
      rm -rf "$(dirname "$f")/planted" "$f"
    done
    # control: the old allowlist (a tests/ folder entry, no default rules) lets the same key through
    cp .gitleaks.toml "$T/gl.toml"; printf 'title = "old"\n[allowlist]\n  paths = [\x27\x27\x27tests/\x27\x27\x27]\n' > .gitleaks.toml
    k=$(key); printf 'TOKEN = "%s"\n' "$k" > backend/tests/test_planted.py; git add .gitleaks.toml backend/tests/test_planted.py
    git commit -q -m control >"$T/c3" 2>&1 && git reset -q --soft HEAD~1
    grep -q "Detect hardcoded secrets.*Passed" "$T/c3" && ok "control: with the old allowlist gitleaks lets the same key through (the fix is what catches it)" \
      || bad "control: gitleaks refused the key even with the old allowlist -- the key test proves nothing about the fix"
    git reset -q
    cp "$T/gl.toml" .gitleaks.toml; rm -f backend/tests/test_planted.py; git checkout -q -- . 2>/dev/null
    # 5. a .tsx and a .py save on work with Docker absent: the frontend checks say they skipped, the save goes through
    nd_path=$(printf '%s' "$PATH" | tr ':' '\n' | while read -r p; do [ -x "$p/docker" ] || printf '%s:' "$p"; done)
    printf 'export const planted = "hello";\n' > frontend/lib/planted.ts
    printf 'export function Planted() {\n  return <p>hello</p>;\n}\n' > frontend/components/planted.tsx
    printf 'def planted() -> str:\n    return "hello"\n' > backend/app/planted.py
    git add frontend/lib/planted.ts frontend/components/planted.tsx backend/app/planted.py
    if PATH="$nd_path" git commit -m "frontend and backend, no Docker" >"$T/c4" 2>&1; then
      grep -q "SKIPPED: the eslint check of your frontend code, because Docker isn't installed" "$T/c4" && grep -q "CI runs this check" "$T/c4" \
        && ok "no Docker: a .tsx and a .py save go through, the frontend checks print their skip line" || bad "no Docker: saved without the skip line: $(grep -i eslint "$T/c4")"
    else bad "no Docker: a .tsx/.py save was refused: $(tail -6 "$T/c4")"; fi
    # 6. with Docker: the frontend checks run in the container -- a clean change passes, a badly formatted one is refused
    if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
      printf 'export const planted2 = "hello";\n' > frontend/lib/planted2.ts; git add frontend/lib/planted2.ts
      s=$(date +%s)
      if git commit -m "frontend with Docker" >"$T/c5" 2>&1; then
        grep -q "SKIPPED" "$T/c5" && bad "with Docker: the frontend checks skipped: $(grep SKIPPED "$T/c5")" || ok "with Docker: a clean .ts save passes eslint and prettier in the container ($(( $(date +%s) - s ))s, first run builds the packages)"
      else bad "with Docker: a clean .ts save was refused: $(tail -8 "$T/c5")"; fi
      printf 'export   const   ugly={a:1}\n' > frontend/lib/ugly.ts; git add frontend/lib/ugly.ts
      s=$(date +%s)
      if git commit -m "badly formatted" >"$T/c6" 2>&1; then bad "with Docker: a badly formatted file was saved"
      else grep -qi "prettier.*Failed\|eslint.*Failed" "$T/c6" && ok "with Docker: a badly formatted .ts file is refused by the container checks ($(( $(date +%s) - s ))s, warm)" || bad "with Docker: refused, but not by the frontend checks: $(tail -6 "$T/c6")"; fi
      git reset -q; rm -f frontend/lib/ugly.ts
    else echo "SKIPPED  Part 3.6 (frontend checks in the container): Docker isn't running here -- NOT PROVEN on this machine"; fi
  fi
  cd "$OLDROOT"
fi

[ "$fail" = 0 ] && echo "PASS test-git-guards" || echo "FAILED test-git-guards"
exit $fail
